static_assert(sizeof(PioneerQ38RecurrentBlockPeerGdn)==35564,"exact complete PeerGdn DATA");
static inline bool PioneerQ38RecurrentBlockProgramWord(unsigned w,uint32_t a,uint32_t& output){
 if(w>=120 || (a&3))return false;
 for(unsigned n=0;n<PioneerQ38RecurrentBlockCodeSpans(w);n++){
  const auto s=PioneerQ38RecurrentBlockCodeSpan(w,n);if(a<s.address || a-s.address>=s.words*4)continue;
  const uint32_t* data=nullptr;
  if(!w)switch(n){
   case 0:data=PioneerQ38RecurrentBlockRootBoot;break;
   case 1:data=PioneerQ38RecurrentBlockRootText;break;
   case 2:data=PioneerQ38RecurrentBlockRootConv;break;
  }else switch(n){
   case 0:data=PioneerQ38RecurrentBlockPeerBoot;break;
   case 1:data=PioneerQ38RecurrentBlockPeerMixed;break;
   case 2:data=PioneerQ38RecurrentBlockPeerDense;break;
   case 3:data=PioneerQ38RecurrentBlockPeerFfn;break;
   case 4:data=PioneerQ38RecurrentBlockPeerOutput;break;
   case 5:data=PioneerQ38RecurrentBlockPeerAffine;break;
   case 6:data=PioneerQ38RecurrentBlockPeerService;break;
   case 7:data=PioneerQ38RecurrentBlockPeerGdn;break;
  }
  if(!data){return false;}output=data[(a-s.address)/4];return true;
 }
 return false; // caller output untouched;NO executable padding or runtime grant
}
